enum class Urgensi(val labelId: String, val deskripsiTindakan: String) {
    EDUKASI_MANDIRI("Edukasi Mandiri", "Perawatan kebersihan gigi mandiri di rumah"),
    KONTROL_RUTIN("Kontrol Rutin", "Jadwalkan pemeriksaan rutin ke dokter gigi"),
    SEGERA_KE_DOKTER("Segera ke Dokter", "Segera konsultasi langsung ke dokter gigi atau klinik terdekat")
}

data class DetectionResult(
    val kelas: String,
    val confidence: Float,
