object DiseaseDescriptions {
    fun normalize(kelas: String): String =
        kelas.trim().lowercase().replace("_", " ").replace(Regex("\\s+"), " ")

    fun getDescription(kelas: String): String {
        val k = normalize(kelas)
        return when {
            "calculus" in k ->
                "Kalkulus (karang gigi) adalah lapisan plak yang mengeras pada permukaan gigi dan garis gusi. Lapisan ini tidak dapat dibersihkan hanya dengan sikat gigi biasa dan memerlukan pembersihan profesional (scaling)."
            "caries" in k ->
                "Karies adalah kerusakan jaringan keras gigi akibat asam dari bakteri plak yang menyebabkan gigi berlubang. Jika dibiarkan, kerusakan dapat semakin dalam dan menimbulkan nyeri maupun infeksi."
            "gingivitis" in k ->
                "Gingivitis adalah peradangan gusi akibat penumpukan plak di sekitar garis gusi. Gejalanya meliputi gusi kemerahan, bengkak, mudah berdarah saat menyikat gigi, dan bau mulut."
            "hypodontia" in k ->
                "Hypodontia adalah kondisi perkembangan bawaan di mana satu atau lebih gigi permanen tidak tumbuh. Kondisi ini dapat memengaruhi fungsi kunyah serta susunan gigi sehingga perlu evaluasi dokter gigi."
            "ulcer" in k ->
                "Sariawan (mouth ulcer) adalah luka terbuka kecil pada mukosa mulut yang sering terasa perih saat makan atau minum. Sebagian besar sembuh dalam 1–2 minggu, namun segera periksa bila berlangsung lebih dari 2–3 minggu."
            "discoloration" in k ->
                "Perubahan warna gigi (tooth discoloration) disebabkan oleh noda makanan/minuman berpigmen (kopi, teh), kebiasaan merokok, kurangnya kebersihan mulut, atau faktor internal struktur gigi."
            else ->
                "Hasil deteksi awal kondisi gigi dan mulut. Konsultasikan dengan dokter gigi untuk pemeriksaan klinis lebih lanjut."
        }
    }

    fun defaultUrgensiFor(kelas: String, confidence: Float = 0.85f): Urgensi {
        val k = normalize(kelas)
        return when {
            "caries" in k || "hypodontia" in k -> Urgensi.SEGERA_KE_DOKTER
            "calculus" in k || "gingivitis" in k || "ulcer" in k -> Urgensi.KONTROL_RUTIN
            "discoloration" in k -> Urgensi.EDUKASI_MANDIRI
            else -> Urgensi.KONTROL_RUTIN
        }
    }
}
